package com.order.order_service.service;
import com.order.order_service.client.*;import com.order.order_service.entity.Order;import com.order.order_service.repository.*;import jakarta.persistence.EntityNotFoundException;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service @Transactional(readOnly=true) public class OrderQueryService {private final OrderRepository orders;private final OrderItemRepository items;private final DeliveryClient delivery;private final CatalogClient catalog;public OrderQueryService(OrderRepository o,OrderItemRepository i,DeliveryClient d,CatalogClient c){orders=o;items=i;delivery=d;catalog=c;}
 public List<Map<String,Object>> mine(long user){return orders.findByUserId(user).stream().sorted(Comparator.comparing(Order::getCreatedAt).reversed()).map(this::view).toList();}
 public List<Map<String,Object>> all(){return orders.findAll().stream().sorted(Comparator.comparing(Order::getCreatedAt).reversed()).map(this::view).toList();}
 public List<Map<String,Object>> ownerOrders(long owner){return orders.findAll().stream().filter(o->items.findByOrderIdOrderById(o.getId()).stream().anyMatch(i->{if(i.getRestaurantId()==null||i.getRestaurantId()<=0)return false;try{Object id=catalog.getRestaurant(i.getRestaurantId()).get("ownerId");return id instanceof Number n&&n.longValue()==owner;}catch(feign.FeignException.NotFound missingRestaurant){return false;}})).sorted(Comparator.comparing(Order::getCreatedAt).reversed()).map(this::view).toList();}
 public Map<String,Object> one(long id){return view(orders.findById(id).orElseThrow(()->new EntityNotFoundException("Order not found")));}
 public boolean ownedByRestaurantOwner(long orderId,long owner){Order o=orders.findById(orderId).orElseThrow(()->new EntityNotFoundException("Order not found"));return items.findByOrderIdOrderById(orderId).stream().anyMatch(i->{if(i.getRestaurantId()==null||i.getRestaurantId()<=0)return false;try{Object id=catalog.getRestaurant(i.getRestaurantId()).get("ownerId");return id instanceof Number n&&n.longValue()==owner;}catch(feign.FeignException.NotFound missing){return false;}});}
 public Map<String,Object> driverLocation(long id,String token){return delivery.location(id,"Bearer "+token);}
 private Map<String,Object> view(Order o){var lines=items.findByOrderIdOrderById(o.getId()).stream().map(i->{Map<String,Object> l=new LinkedHashMap<>();l.put("id",i.getId());l.put("menuItemId",i.getMenuItemId());l.put("restaurantId",i.getRestaurantId());l.put("itemName",i.getItemName());l.put("unitPrice",i.getUnitPrice());l.put("quantity",i.getQuantity());l.put("subtotal",i.getUnitPrice().multiply(java.math.BigDecimal.valueOf(i.getQuantity())));return l;}).toList();Map<String,Object> m=new LinkedHashMap<>();m.put("id",o.getId());m.put("orderNumber","ORD-"+o.getId());m.put("userId",o.getUserId());m.put("status",o.getStatus().name());m.put("items",lines);m.put("totalAmount",o.getAmount());m.put("deliveryAddress",Objects.toString(o.getDeliveryAddress(),""));m.put("createdAt",o.getCreatedAt());return m;}
}
